properties.JSLT Transformation:
let matches =
  [for (.)
    .
    if (.serialno == "${ham.serialno}")
  ]

let sensor = $matches[0]

{
  "found": size($matches) > 0,

  "csv_header":
    if (size($matches) > 0)
      join(
        flatten([
          ["timestamp"],
          [for (array($sensor.state.R)) .key]
        ]),
        ";"
      ),

  "observation_count":
    if (size($matches) > 0)
      size(array($sensor.state.R))
}

def transform_value(raw, transform)
  if ($transform == "divide_by_10")
    $raw / 10
  else if ($transform == "divide_by_100")
    $raw / 100
  else if ($transform == "divide_by_1000")
    $raw / 1000
  else if ($transform == "divide_by_10000")
    $raw / 10000
  else if ($transform == "divide_by_100000")
    $raw / 100000
  else if ($transform == "divide_by_1000000")
    $raw / 1000000
  else if ($transform == "divide_by_100_max_100")
    $raw / 100
  else if ($transform == "divide_by_1000_max_100")
    $raw / 1000
  else
    $raw

def unpivot_row(row, mapping, sensor_id)
  [for ($row)
    let key = .key
    let meta = get-key($mapping, $key)

    {
      "sensor_id": $sensor_id,
      "observation_type_id": $meta.observation_type_uuid,
      "timestamp": round(number($row.timestamp) * 1000),
      "value": transform_value(number(.value), $meta.transform)
    }

    if ($key != "timestamp")
  ]

let mapping = ${ham.observation.mapping}
let sensor_id = "${sensor.db_uuid}"

flatten(
  [for (.)
    unpivot_row(., $mapping, $sensor_id)
  ]
)

properties.SQL Query:
SELECT MAX(timestamp) AS checkpoint_timestamp
FROM observation_values
WHERE sensor_id = '${sensor.db_uuid}';

properties.JSLT Transformation:
[for (.)
  let reading = .value

  {
    "key": .key,
    "label": $reading.label,
    "unit": $reading.unit,
    "sensor_family": "ham",
    "type_metadata": to-json(
      $reading | {
        * - label, unit : .
      }
    )
  }

  if (
  $reading.label != null
  and $reading.label != ""
  and $reading.unit != null
  and $reading.unit != ""
)
]

properties.SQL Query:
SELECT EXISTS (
    SELECT 1
    FROM public.observation_types
    WHERE sensor_family = 'ham'
) AS ready;
